/**
 * notices — the open-source licence notices the site serves at /licenses/.
 *
 * Generated by the production build (licensesPlugin, wired in vite.config.ts), never typed:
 *
 *   licenses/index.html            what is here, the Hub's own licence, the source link
 *   licenses/npm-packages.txt      every npm package whose code the build puts in its chunks,
 *                                  plus packages whose files are copied into the site as they
 *                                  are, each with the licence files it ships
 *   licenses/engines/<bundle>.txt  every served WebAssembly engine: its third-party contents,
 *                                  their licences and the full licence texts
 *
 * Inputs: the build's own chunk graph (which packages ship), node_modules (their licence
 * files), src/data/licenses/ (engine contents, upstream texts, crate licence files), the
 * served binaries (which Rust crates each one contains) and the engine build records
 * (wasm-provenance.json, sbomWasmArtifacts.json). The build FAILS when a shipped package or
 * crate has no licence, an engine has no notices entry, or a named text is missing.
 */
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'
import type { Plugin } from 'vite'
import { scanRustWasm } from './wasm-scan.mjs'
import { lockKeyOf } from './vite-plugin-bundle-packages'

export const LICENSE_FILE =
  /^(LICEN[CS]E|COPYING|NOTICE|UNLICENSE|COPYRIGHT|ThirdPartyNotices)([-._].*)?$/i
const DATA = 'src/data/licenses'
const REPO = 'https://github.com/pqctoday-org/pqctoday-hub'
const RULE = '='.repeat(78)
const THIN = '-'.repeat(78)

const readJson = <T>(root: string, rel: string): T =>
  JSON.parse(readFileSync(join(root, rel), 'utf8')) as T

interface Component {
  name: string
  license: string
  texts: string[]
  changes?: string
  note?: string
  sourceOffer?: string[]
}
interface EngineConfig {
  textSources: Record<string, string>
  toolchains: Record<string, Component[]>
  bundles: {
    key: string
    title: string
    toolchain: string | null
    alsoToolchain?: string
    noticesFile?: string
    licensesDir?: string
    components: Component[]
    incomplete: string[]
  }[]
}
interface NpmConfig {
  servedCopies: Record<string, string>
  upstreamTexts: Record<string, { texts: string[]; note: string }>
  elections: Record<string, { use: string; offered: string }>
  otherServedFiles: Component[]
}
interface CrateTexts {
  commit: string
  crates: Record<string, { license: string; source: string; files: Record<string, string> }>
  texts: Record<string, string>
}

/** Declared licence of a package.json, in whichever of the historical shapes it uses. */
export function declaredLicense(pkg: Record<string, unknown>): string | undefined {
  const l = pkg.license as unknown
  if (typeof l === 'string' && l.trim()) return l.trim()
  if (l && typeof l === 'object' && typeof (l as { type?: string }).type === 'string')
    return (l as { type: string }).type
  const ls = pkg.licenses as unknown
  if (Array.isArray(ls) && ls.length)
    return ls.map((x) => (typeof x === 'string' ? x : (x as { type?: string }).type)).join(' OR ')
  return undefined
}

/** SPDX identifiers in an expression ("(MIT OR Apache-2.0)" -> ["MIT", "Apache-2.0"]). */
export function spdxIds(expr: string): string[] {
  return expr
    .replace(/[()]/g, ' ')
    .split(/\s+(?:OR|AND|WITH)\s+|\s*\/\s*/)
    .map((t) => t.trim())
    .filter(Boolean)
}

function authorOf(pkg: Record<string, unknown>): string | undefined {
  const a = pkg.author as unknown
  if (typeof a === 'string' && a.trim()) return a.replace(/\s*<[^>]*>/, '').trim()
  if (a && typeof a === 'object' && typeof (a as { name?: string }).name === 'string')
    return (a as { name: string }).name
  return undefined
}

function readText(root: string, rel: string, problems: string[]): string {
  const p = join(root, DATA, 'texts', rel)
  if (!existsSync(p)) {
    problems.push(`licence text ${DATA}/texts/${rel} is missing`)
    return ''
  }
  return readFileSync(p, 'utf8')
}

function standardText(root: string, id: string): string | undefined {
  const p = join(root, DATA, 'texts', 'spdx', `${id}.txt`)
  return existsSync(p) ? readFileSync(p, 'utf8') : undefined
}

// ---------------------------------------------------------------------------- npm

export interface NpmEntry {
  key: string
  name: string
  version: string
  license: string
  servedAs?: string
  election?: { use: string; offered: string }
  files: { name: string; text: string }[]
  note?: string
}

export function collectNpm(
  root: string,
  bundledKeys: readonly string[]
): { entries: NpmEntry[]; problems: string[] } {
  const cfg = readJson<NpmConfig>(root, `${DATA}/npmNotices.json`)
  const problems: string[] = []
  const keys = new Set(bundledKeys)
  for (const name of Object.keys(cfg.servedCopies)) keys.add(`node_modules/${name}`)
  const entries: NpmEntry[] = []
  for (const key of [...keys].sort()) {
    const dir = join(root, key)
    const manifest = join(dir, 'package.json')
    if (!existsSync(manifest)) {
      problems.push(`${key}: shipped but not installed (no package.json) — run npm ci`)
      continue
    }
    const pkg = JSON.parse(readFileSync(manifest, 'utf8')) as Record<string, unknown>
    const name = String(pkg.name ?? key.slice(key.lastIndexOf('node_modules/') + 13))
    const files = readdirSync(dir)
      .filter((f) => LICENSE_FILE.test(f) && statSync(join(dir, f)).isFile())
      .sort()
      .map((f) => ({ name: f, text: readFileSync(join(dir, f), 'utf8') }))
    let license = declaredLicense(pkg)
    let note: string | undefined
    if (!license && files.length) {
      license = 'see the licence file below (none declared in package.json)'
    }
    if (!license) {
      problems.push(`${name}@${pkg.version}: shipped with no declared licence and no licence file`)
      continue
    }
    const upstream = cfg.upstreamTexts[name]
    if (!files.length && upstream) {
      for (const t of upstream.texts)
        files.push({ name: `upstream ${t}`, text: readText(root, t, problems) })
      note = upstream.note
    } else if (!files.length) {
      const election = cfg.elections[name]
      const ids = election ? [election.use] : spdxIds(license)
      const author = authorOf(pkg) ?? `the ${name} authors`
      for (const id of ids) {
        const t = standardText(root, id)
        if (!t) {
          problems.push(
            `${name}@${pkg.version}: ships no licence file and there is no standard text for "${id}" in ${DATA}/texts/spdx/`
          )
          continue
        }
        files.push({
          name: `standard ${id} text`,
          text: t.replace('<year> <copyright holders>', author),
        })
      }
      note = `The package ships no licence file; this is the standard text of its declared licence, naming the author from its package.json (${author}).`
    }
    entries.push({
      key,
      name,
      version: String(pkg.version ?? ''),
      license,
      servedAs: cfg.servedCopies[name],
      election: cfg.elections[name],
      files,
      note,
    })
  }
  return { entries, problems }
}

export function renderNpm(root: string, entries: NpmEntry[], problems: string[]): string {
  const cfg = readJson<NpmConfig>(root, `${DATA}/npmNotices.json`)
  const out: string[] = []
  out.push(
    'PQC Today Hub - open-source licences of the npm packages the site ships',
    RULE,
    '',
    `${entries.length} packages. A package is listed when the production build puts its code in`,
    'the site, or when the build copies its files into the site as they are. Development',
    'tools that do not ship are not listed. Each entry is followed by the licence and notice',
    'files the package itself ships.',
    '',
    'Index',
    THIN
  )
  for (const e of entries)
    out.push(
      `${e.name} ${e.version} - ${e.election ? `${e.election.use} (used under; offered as ${e.election.offered})` : e.license}${e.servedAs ? ` - served as ${e.servedAs}` : ''}`
    )
  for (const c of cfg.otherServedFiles) out.push(`${c.name} - ${c.license}`)
  out.push('')
  for (const e of entries) {
    out.push(RULE, `${e.name} ${e.version}`, `Licence: ${e.license}`)
    if (e.election)
      out.push(
        `Used by PQC Today under: ${e.election.use} (the package is offered under ${e.election.offered})`
      )
    if (e.servedAs) out.push(`Served as: ${e.servedAs}`)
    if (e.key !== `node_modules/${e.name}`) out.push(`Installed at: ${e.key}`)
    if (e.note) out.push(`Note: ${e.note}`)
    for (const f of e.files) out.push(THIN, `[${f.name}]`, '', f.text.trimEnd())
    out.push('')
  }
  for (const c of cfg.otherServedFiles) {
    out.push(RULE, c.name, `Licence: ${c.license}`)
    for (const t of c.texts) out.push(THIN, `[${t}]`, '', readText(root, t, problems).trimEnd())
    out.push('')
  }
  return out.join('\n') + '\n'
}

// ------------------------------------------------------------------------- engines

interface Provenance {
  hsmRepo: string
  bundles: { name: string; files: string[]; hsmCommit: string | null }[]
}
interface Artifacts {
  artifacts: {
    key: string
    label: string
    repo: string | null
    commit: string | null
    files: Record<string, string>
    lockFiles?: string[]
  }[]
}
interface RustLock {
  forks: Record<string, { crate: string; version: string; license: string }>
  unscannable: Record<string, { versions: string[]; license: string }>
}

export interface EngineNotice {
  key: string
  title: string
  text: string
  incomplete: string[]
  crateCount: number
}

export function collectEngines(root: string): { engines: EngineNotice[]; problems: string[] } {
  const problems: string[] = []
  const cfg = readJson<EngineConfig>(root, `${DATA}/engineNotices.json`)
  const prov = readJson<Provenance>(root, 'public/wasm/wasm-provenance.json')
  const arts = readJson<Artifacts>(root, 'src/data/sbomWasmArtifacts.json')
  const crateTexts = readJson<CrateTexts>(root, `${DATA}/crateLicenseTexts.json`)
  const rustLock = readJson<RustLock>(root, 'src/data/sbomRustLock.json')

  const served = new Map<
    string,
    { files: string[]; source: string; repo: string | null; commit: string | null }
  >()
  for (const b of prov.bundles)
    served.set(b.name, {
      files: b.files.filter((f) => f.startsWith('public/')),
      repo: prov.hsmRepo,
      commit: b.hsmCommit,
      source: b.hsmCommit
        ? `https://github.com/${prov.hsmRepo}/tree/${b.hsmCommit}`
        : 'build commit not recorded',
    })
  for (const a of arts.artifacts)
    served.set(a.key, {
      files: [...Object.keys(a.files), ...(a.lockFiles ?? [])],
      repo: a.repo,
      commit: a.commit,
      source:
        a.repo && a.commit
          ? `https://github.com/${a.repo}/tree/${a.commit}`
          : 'origin not recorded',
    })
  const configured = new Set(cfg.bundles.map((b) => b.key))
  for (const key of served.keys())
    if (!configured.has(key))
      problems.push(
        `engine bundle "${key}" is served but has no entry in ${DATA}/engineNotices.json`
      )
  for (const key of configured)
    if (!served.has(key))
      problems.push(`${DATA}/engineNotices.json lists "${key}", which is not a served bundle`)
  for (const t of Object.keys(cfg.textSources))
    if (!existsSync(join(root, DATA, 'texts', t)))
      problems.push(`${DATA}/engineNotices.json textSources names a missing file texts/${t}`)

  const forkByDir = rustLock.forks
  const engines: EngineNotice[] = []
  for (const b of cfg.bundles) {
    const s = served.get(b.key)
    if (!s) continue
    const out: string[] = []
    const incomplete = [...b.incomplete]
    out.push(
      `Third-party notices - ${b.title}`,
      RULE,
      '',
      `Served files: ${s.files.map((f) => '/' + f.replace(/^public\//, '')).join(', ')}`,
      `Built from:   ${s.source}`,
      ''
    )
    for (const t of b.components.flatMap((c) => c.texts))
      if (!cfg.textSources[t]) problems.push(`${b.key}: text "${t}" has no entry in textSources`)

    // Rust crates, read from the served binaries themselves.
    const rust = b.toolchain === 'rust' || b.alsoToolchain === 'rust'
    const crates = new Map<
      string,
      { license: string; source: string; files: Record<string, string>; changed: boolean }
    >()
    if (rust) {
      let forksSeen = false
      for (const f of s.files.filter((x) => x.endsWith('.wasm'))) {
        if (!existsSync(join(root, f))) {
          problems.push(`${b.key}: ${f} is missing, cannot read its crates`)
          continue
        }
        const scan = scanRustWasm(join(root, f)) as {
          crates: Record<string, string[]>
          forks: string[]
        }
        for (const [name, versions] of Object.entries(scan.crates))
          for (const v of versions) {
            const rec = crateTexts.crates[`${name}@${v}`]
            if (!rec)
              problems.push(
                `crate ${name}@${v} (in ${f}): no licence files in ${DATA}/crateLicenseTexts.json — run \`npm run sbom:refresh-crate-license-texts\``
              )
            else crates.set(`${name}@${v}`, { ...rec, changed: false })
          }
        for (const dir of scan.forks) {
          forksSeen = true
          const fork = forkByDir[dir]
          const rec = fork && crateTexts.crates[`${fork.crate}@${fork.version}`]
          if (!rec) problems.push(`${b.key}: vendored crate ${dir} in ${f} has no licence record`)
          else crates.set(`${fork.crate}@${fork.version}`, { ...rec, changed: true })
        }
      }
      // Crates the scan cannot see are recorded for the engine build; they come with its forks.
      if (forksSeen)
        for (const [name, entry] of Object.entries(rustLock.unscannable))
          for (const v of entry.versions) {
            const rec = crateTexts.crates[`${name}@${v}`]
            if (!rec) problems.push(`crate ${name}@${v} (lock-only): no licence files recorded`)
            else crates.set(`${name}@${v}`, { ...rec, changed: false })
          }
    }

    const toolchain = [
      ...(b.toolchain ? (cfg.toolchains[b.toolchain] ?? []) : []),
      ...(b.alsoToolchain ? (cfg.toolchains[b.alsoToolchain] ?? []) : []),
    ]
    const components = [...b.components, ...toolchain]
    if (b.noticesFile) {
      out.push(
        'This bundle ships its own notices file, reproduced below with its licence texts.',
        ''
      )
    } else if (!components.length && !crates.size) {
      out.push('No third-party contents are recorded for this bundle.', '')
    } else {
      out.push('Contents', THIN)
      for (const c of components) out.push(`- ${c.name} - ${c.license}`)
      if (crates.size)
        out.push(
          `- ${crates.size} Rust crates, listed below (read from the binary; licence files as each crate publishes them)`
        )
      out.push('')
    }
    if (incomplete.length) {
      out.push('Not yet covered by these notices', THIN)
      for (const i of incomplete) out.push(`- ${i}`)
      out.push('')
    }

    const seenText = new Set<string>()
    for (const c of components) {
      out.push(RULE, c.name, `Licence: ${c.license}`)
      if (c.changes) out.push(`Changes: ${c.changes}`)
      if (c.note) out.push(`Note: ${c.note}`)
      for (const o of c.sourceOffer ?? []) out.push(`Source: ${o}`)
      for (const t of c.texts) {
        out.push(THIN, `[${t}] from ${cfg.textSources[t] ?? 'unrecorded source'}`)
        if (seenText.has(t)) out.push('', '(same text as reproduced above)')
        else out.push('', readText(root, t, problems).trimEnd())
        seenText.add(t)
      }
      out.push('')
    }

    if (crates.size) {
      out.push(RULE, 'Rust crates', THIN)
      const sorted = [...crates.entries()].sort(([a], [b2]) => a.localeCompare(b2))
      for (const [k, c] of sorted)
        out.push(`${k} - ${c.license} - ${c.source}${c.changed ? ' - modified by PQC Today' : ''}`)
      out.push('')
      // Each distinct licence file once, with the crates that ship it.
      const byText = new Map<string, string[]>()
      for (const [k, c] of sorted)
        for (const [fname, h] of Object.entries(c.files))
          byText.set(h, [...(byText.get(h) ?? []), `${k} (${fname})`])
      for (const [h, who] of byText) {
        const text = crateTexts.texts[h]
        if (text === undefined) {
          problems.push(`crateLicenseTexts.json: text ${h} referenced but missing`)
          continue
        }
        out.push(THIN, `Shipped by: ${who.join(', ')}`, '', text.trimEnd(), '')
      }
    }

    if (b.noticesFile) {
      const p = join(root, b.noticesFile)
      if (!existsSync(p)) problems.push(`${b.key}: ${b.noticesFile} is missing`)
      else
        out.push(
          RULE,
          `[${b.noticesFile.replace(/^public/, '')}]`,
          '',
          readFileSync(p, 'utf8').trimEnd(),
          ''
        )
      if (b.licensesDir) {
        const d = join(root, b.licensesDir)
        for (const f of existsSync(d) ? readdirSync(d).sort() : [])
          out.push(
            THIN,
            `[${relative(join(root, 'public'), join(d, f))}]`,
            '',
            readFileSync(join(d, f), 'utf8').trimEnd(),
            ''
          )
      }
    }
    engines.push({
      key: b.key,
      title: b.title,
      text: out.join('\n') + '\n',
      incomplete,
      crateCount: crates.size,
    })
  }
  return { engines, problems }
}

// --------------------------------------------------------------------------- index

const esc = (s: string) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

export function renderIndex(o: {
  version: string
  commit: string
  license: string
  npmCount: number
  engines: EngineNotice[]
}): string {
  const tree = /^[0-9a-f]{40}$/.test(o.commit) ? `${REPO}/tree/${o.commit}` : REPO
  const licenseUrl = /^[0-9a-f]{40}$/.test(o.commit)
    ? `${REPO}/blob/${o.commit}/LICENSE`
    : `${REPO}/blob/main/LICENSE`
  const rows = o.engines
    .map(
      (e) =>
        `<li><a href="engines/${esc(e.key)}.txt">${esc(e.title)}</a>${e.crateCount ? ` <span class="m">(${e.crateCount} Rust crates)</span>` : ''}${
          e.incomplete.length
            ? `<ul class="m">${e.incomplete.map((i) => `<li>Not yet covered: ${esc(i)}</li>`).join('')}</ul>`
            : ''
        }</li>`
    )
    .join('\n')
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>Open-source licences - PQC Today</title>
<style>
:root{--bg:#fff;--fg:#1a1a1a;--muted:#555;--link:#0b5cad}
@media (prefers-color-scheme:dark){:root{--bg:#0f1115;--fg:#e8e8e8;--muted:#a0a0a0;--link:#7cb7ff}}
body{background:var(--bg);color:var(--fg);font:16px/1.55 system-ui,sans-serif;margin:0 auto;max-width:46rem;padding:24px 16px}
a{color:var(--link)} .m{color:var(--muted);font-size:.92em} h1{font-size:1.6rem} h2{font-size:1.2rem;margin-top:2rem}
</style>
</head>
<body>
<h1>Open-source licences</h1>
<p>PQC Today Hub version ${esc(o.version)}. <a href="/">Back to the site</a>.</p>
<h2>The Hub's own code</h2>
<p>Licence: ${esc(o.license)}, see <a href="${esc(licenseUrl)}">LICENSE</a>. Source code of this version: <a href="${esc(tree)}">${esc(tree.replace('https://', ''))}</a>.</p>
<h2>npm packages in the site</h2>
<p><a href="npm-packages.txt">${o.npmCount} packages, with the licence files each one ships</a>. Listed from the production build itself: every package whose code ends up in the site, and packages whose files are served as they are.</p>
<h2>WebAssembly engines</h2>
<p>Each engine's third-party contents, their licences and the full licence texts. The engine repositories will also ship their own notices with each release.</p>
<ul>
${rows}
</ul>
<p class="m">Generated by the build from the shipped files and their records. The SBOM on the About page lists the same components with versions.</p>
</body>
</html>
`
}

// -------------------------------------------------------------------------- plugin

export function buildNotices(
  root: string,
  bundledKeys: readonly string[],
  meta: { version: string; commit: string }
): { files: Record<string, string>; problems: string[] } {
  const npm = collectNpm(root, bundledKeys)
  const eng = collectEngines(root)
  const problems = [...npm.problems, ...eng.problems]
  const pkg = readJson<{ license?: string }>(root, 'package.json')
  const files: Record<string, string> = {
    'licenses/npm-packages.txt': renderNpm(root, npm.entries, problems),
    'licenses/index.html': renderIndex({
      version: meta.version,
      commit: meta.commit,
      license: pkg.license ?? 'see LICENSE',
      npmCount: npm.entries.length,
      engines: eng.engines,
    }),
  }
  for (const e of eng.engines) files[`licenses/engines/${e.key}.txt`] = e.text
  return { files, problems }
}

/** Emits /licenses/ into the production build; fails the build on any missing licence. */
export function licensesPlugin(root: string, meta: { version: string; commit: string }): Plugin {
  return {
    name: 'licence-notices',
    apply: 'build',
    generateBundle(_options, bundle) {
      const keys = new Set<string>()
      for (const chunk of Object.values(bundle)) {
        if (chunk.type !== 'chunk') continue
        for (const id of Object.keys(chunk.modules)) {
          const key = lockKeyOf(id)
          if (key) keys.add(key)
        }
      }
      const { files, problems } = buildNotices(root, [...keys], meta)
      if (problems.length)
        this.error(`licence notices: ${problems.length} problem(s)\n  ${problems.join('\n  ')}`)
      for (const [fileName, source] of Object.entries(files))
        this.emitFile({ type: 'asset', fileName, source })
    },
  }
}
